// Jacinta's pixel-art animation frames for the Storybook (Chapter 3).
// Made from the two sprite sheets you supplied (friendly face + determined face):
// each frame was scaled to game size (about 82 pixels tall), given one shared
// colour palette, and lined up so her feet sit on the same spot in every frame.
// The picture is also saved as assets/jacinta/jacinta_sheet.png.
//
// Sheet layout: 8 columns. Rows 0-4 = friendly face, rows 5-9 = determined face.
//   row 0 idle · row 1 walk · row 2 crouch · row 3 run · row 4 jump   (+5 for determined)
//
// ---- EASY SETTINGS -------------------------------------------------------
// fps:       frames per second for idle and crouch
// stepPx:    how far she moves (game pixels) per walk/run frame. Bigger = slower
//            legs. Matching this to her real speed keeps her feet from sliding.
// determinedHold: seconds she keeps her determined face after a reason ends
// --------------------------------------------------------------------------
export const JACINTA_ANIM = {
  idle: { row: 0, frames: [0, 1, 2, 3, 4, 5, 6, 7], fps: 6 },
  walk: { row: 1, frames: [0, 1, 2, 3, 4, 5, 6, 7], stepPx: 9.5 },
  run: { row: 3, frames: [1, 2, 3, 4, 5, 6, 7], stepPx: 15.5 },
  jump: { row: 4 }, // 0 crouch · 1 take-off · 2 rising · 3 tuck · 4 top · 5 falling · 6 landing squat · 7 stand up
  crouch: { row: 2 }, // 1 = flinch when bumped
  landFrameTime: 0.07,
  determinedHold: 0.9,
};

export const JACINTA_SHEET = {
  cellW: 98, cellH: 110,
  anchorX: 60, anchorY: 108, // her feet, centred under her shirt
  rowsPerFace: 5, faces: { friendly: 0, determined: 5 },
  url: 'data:image/png;base64,',
};
